package com.cloudtv.iptv.repository

import android.content.Context
import android.content.SharedPreferences
import com.cloudtv.iptv.model.BufferMode
import com.cloudtv.iptv.model.ChannelGroup
import com.cloudtv.iptv.model.TvChannel
import com.cloudtv.iptv.network.Ipv4OnlyDns
import com.cloudtv.iptv.parser.PlaylistParser
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import java.io.File
import java.util.concurrent.TimeUnit

/**
 * 频道与直播源数据仓库 (ChannelRepository)
 * =========================================================================
 * 1. 内置精选纯 IPv4 多线路央视 + 卫视频道种子库，安装即看，零配置开箱即用；
 * 2. 支持拉取远程 M3U / TXT 订阅链接（含局域网电脑 `iptv_aggregator.py --serve` 提供的测速源），
 *    并可将新订阅源与内置多线路合并或替换；
 * 3. 记忆用户最后观看的频道、收藏频道列表、抗抖动缓冲模式、软硬解偏好及开机自启开关。
 */
class ChannelRepository(private val context: Context) {

    private val prefs: SharedPreferences =
        context.getSharedPreferences("cloudtv_ipv4_prefs", Context.MODE_PRIVATE)
    private val cacheFile = File(context.filesDir, "cached_ipv4_playlist_v2.txt")

    private val httpClient = Ipv4OnlyDns.createHttpClientBuilder(
        connectTimeoutMs = 10_000L,
        readTimeoutMs = 15_000L
    ).build()

    @Volatile
    private var allChannels: List<TvChannel> = emptyList()

    fun loadInitialChannels(): List<TvChannel> {
        val favorites = getFavoriteIds()
        val rawText = if (cacheFile.exists() && cacheFile.length() > 64) {
            cacheFile.readText(Charsets.UTF_8)
        } else {
            BUILTIN_IPV4_PLAYLIST
        }
        val parsed = PlaylistParser.parse(rawText, originTag = "本地纯IPv4源", ipv4Only = true)
        val result = if (parsed.channels.isNotEmpty()) {
            parsed.channels
        } else {
            PlaylistParser.parse(BUILTIN_IPV4_PLAYLIST, originTag = "内置纯IPv4源", ipv4Only = true).channels
        }
        result.forEach { ch -> ch.isFavorite = favorites.contains(ch.id) }
        allChannels = result
        return result
    }

    fun getChannels(): List<TvChannel> = allChannels

    fun getChannelGroups(): List<ChannelGroup> {
        val channels = allChannels
        val groups = mutableListOf<ChannelGroup>()

        val favList = channels.filter { it.isFavorite }
        if (favList.isNotEmpty()) {
            groups.add(ChannelGroup("★ 我的收藏", favList))
        }

        val groupedMap = channels.groupBy { it.groupName }
        for ((grpName, list) in groupedMap) {
            groups.add(ChannelGroup(grpName, list))
        }
        return groups
    }

    /**
     * 从远程 URL 拉取最新 M3U / TXT 直播源（强制纯 IPv4 过滤）
     */
    suspend fun syncFromRemoteUrl(url: String, mergeWithBuiltin: Boolean = true): PlaylistParser.ParseResult =
        withContext(Dispatchers.IO) {
            val req = Request.Builder()
                .url(url.trim())
                .header("User-Agent", "Mozilla/5.0 (Linux; Android 12; Android TV) ExoPlayerLib/2.19.1")
                .build()
            httpClient.newCall(req).execute().use { resp ->
                if (!resp.isSuccessful) {
                    throw IllegalStateException("拉取直播源失败: HTTP ${resp.code}")
                }
                val bodyText = resp.body?.string() ?: throw IllegalStateException("直播源内容为空")
                saveCustomPlaylistContent(bodyText, mergeWithBuiltin)
            }
        }

    /**
     * 保存手机局域网推送过来的自定义 M3U / TXT 文本内容并立即生效
     */
    fun saveCustomPlaylistContent(rawContent: String, mergeWithBuiltin: Boolean = true): PlaylistParser.ParseResult {
        val combinedText = if (mergeWithBuiltin) {
            rawContent + "\n" + BUILTIN_IPV4_PLAYLIST
        } else {
            rawContent
        }
        val parseResult = PlaylistParser.parse(combinedText, originTag = "自定义IPv4源", ipv4Only = true)
        if (parseResult.channels.isEmpty()) {
            throw IllegalArgumentException("未解析出任何有效的纯 IPv4 频道（可能全部为 IPv6 源，已被自动拦截）")
        }
        cacheFile.writeText(combinedText, Charsets.UTF_8)
        val favorites = getFavoriteIds()
        parseResult.channels.forEach { it.isFavorite = favorites.contains(it.id) }
        allChannels = parseResult.channels
        return parseResult
    }

    fun resetToBuiltinPlaylist(): List<TvChannel> {
        if (cacheFile.exists()) cacheFile.delete()
        return loadInitialChannels()
    }

    fun toggleFavorite(channel: TvChannel): Boolean {
        channel.isFavorite = !channel.isFavorite
        val favSet = getFavoriteIds().toMutableSet()
        if (channel.isFavorite) favSet.add(channel.id) else favSet.remove(channel.id)
        prefs.edit().putStringSet(KEY_FAVORITES, favSet).apply()
        return channel.isFavorite
    }

    private fun getFavoriteIds(): Set<String> =
        prefs.getStringSet(KEY_FAVORITES, emptySet()) ?: emptySet()

    var lastChannelId: String
        get() = prefs.getString(KEY_LAST_CHANNEL_ID, "CCTV-1 综合") ?: "CCTV-1 综合"
        set(value) = prefs.edit().putString(KEY_LAST_CHANNEL_ID, value).apply()

    var subscriptionUrl: String
        get() = prefs.getString(KEY_SUB_URL, DEFAULT_REMOTE_IPV4_URL) ?: DEFAULT_REMOTE_IPV4_URL
        set(value) = prefs.edit().putString(KEY_SUB_URL, value.trim()).apply()

    var bufferMode: BufferMode
        get() {
            val saved = prefs.getString(KEY_BUFFER_MODE, BufferMode.BALANCED_ANTI_STUTTER.name)
            return BufferMode.entries.firstOrNull { it.name == saved } ?: BufferMode.BALANCED_ANTI_STUTTER
        }
        set(value) = prefs.edit().putString(KEY_BUFFER_MODE, value.name).apply()

    var preferSoftwareDecoder: Boolean
        get() = prefs.getBoolean(KEY_PREFER_SW_DECODER, false)
        set(value) = prefs.edit().putBoolean(KEY_PREFER_SW_DECODER, value).apply()

    var bootAutoStart: Boolean
        get() = prefs.getBoolean(KEY_BOOT_AUTO_START, false)
        set(value) = prefs.edit().putBoolean(KEY_BOOT_AUTO_START, value).apply()

